class PhaseOperator(nn.Module): # Learn mode-independent dynamic transition phase from nondimensional frequency increment.
    def __init__(self): # Declare the complete learned scalar phase model.
        super().__init__();self.net=nn.Sequential(nn.Linear(1,32),nn.Tanh(),nn.Linear(32,32),nn.Tanh(),nn.Linear(32,1)) # Use a continuous neural function of actual omega times dt.
    def forward(self,z): # Produce a bounded stable rotation angle without using the analytic Newmark angle as a baseline.
        return np.pi*torch.sigmoid(self.net(torch.log1p(z).reshape(-1,1)).squeeze(-1)) # Bound phase to the physically relevant interval and prevent autonomous amplitude blow-up.
def advance(state,g0,g1,theta): # Decode learned phase into a state/force-increment transition.
    c=torch.cos(theta);s=torch.sin(theta);q,v=state.unbind(-1);load=(g0+g1)/2 # Preserve displacement and velocity states and both ends of the load increment.
