def rollout(theta,load): # Evaluate genuinely autoregressive multistep prediction without teacher forcing.
    theta=np.asarray(theta,dtype=np.float64);c=np.cos(theta);s=np.sin(theta);state=np.zeros((len(theta),2));history=[state.copy()] # Start from declared zero displacement and velocity and preserve orthogonality in double precision.
    for step in range(1,len(load)): # Feed each predicted state into the next transition.
        q,v=state.T;g=(load[step-1]+load[step])/2;state=np.column_stack([c*q+s*v+(1-c)*g,-s*q+c*v+s*g]);history.append(state.copy()) # Evolve raw neural phase operator with known forcing only.
    return np.asarray(history) # Return uncorrected physical-state sequence.
def load_data(): # Load only actual qualified geometry/time-history records.
    manifest=json.loads((DYN/'manifest.json').read_text());items=[];assert len(manifest)==112 and len(set(x['geometry_id'] for x in manifest))==56 # Require complete trajectory generation before training or evaluating any split.
