        folder=DYN/'geometries'/row['geometry_id'];data=np.load(folder/f"wave{row['wave']}.npz");geometry=np.load(folder/'modal_geometry.npz');items.append(dict(row,z=data['z'],state=data['state'],load=data['amplitude'],time=data['time'],omega=geometry['omega'],phi=geometry['phi'],modal_force=geometry['modal_force'])) # Resolve portable geometry-relative artifacts while retaining original absolute manifest paths only as historical provenance.
