def error_metrics(prediction,reference,item): # Measure full nodal displacement error using the actual modal decoder Gram matrix.
    scale=item['modal_force']/item['omega']**2;delta=(prediction[:,:,0]-reference[:,:,0])*scale;truth=reference[:,:,0]*scale;G=item['phi'].T@item['phi'];error=np.sqrt(max(float(np.einsum('ti,ij,tj->',delta,G,delta)),0)/max(float(np.einsum('ti,ij,tj->',truth,G,truth)),1e-30)) # Compute exactly the same Euclidean field norm as explicit nodal decoding.
    z=item['z'];q=prediction[:,:,0];v=prediction[:,:,1];g=item['load'];kin=(q[1:]-q[:-1])/z-(v[1:]+v[:-1])/2;moment=(v[1:]-v[:-1])/z+(q[1:]+q[:-1])/2-(g[1:]+g[:-1])[:,None]/2 # Evaluate original discrete kinematics and modal momentum rather than the learned rotation's own equation.
    return {'nodal_displacement_relative_L2':float(error),'state_relative_L2':float(np.linalg.norm(prediction-reference)/max(np.linalg.norm(reference),1e-30)),'discrete_kinematic_relative':float(np.linalg.norm(kin)/max(np.linalg.norm(reference[:,:,1]),1e-30)),'discrete_momentum_relative':float(np.linalg.norm(moment)/max(np.linalg.norm(np.broadcast_to(g[:,None],q.shape)),1e-30))} # Keep field accuracy and governing-equation residuals separate.
def train_all(): # Fit three independent dynamic state operators using geometry-isolated validation.
    items=load_data();training=[x for x in items if x['split']=='train'];validation=[x for x in items if x['split']=='validation'];ztrain=np.concatenate([x['z'] for x in training]);zval=np.concatenate([x['z'] for x in validation]);unique=np.unique(ztrain);model_dir=DYN/'training';model_dir.mkdir(exist_ok=True);models=[];logs=[] # Freeze all training inputs before inspecting tests.
    states=np.concatenate([np.transpose(x['state'],(1,0,2)) for x in training]);loads=np.concatenate([np.broadcast_to(x['load'],(len(x['z']),len(x['load']))) for x in training]);T=states.shape[1];state_tensor=torch.tensor(states,dtype=torch.float32);load_tensor=torch.tensor(loads,dtype=torch.float32);zt=torch.tensor(ztrain,dtype=torch.float32) # Build genuine modal state windows from actual FEM-eigenproblem trajectories.
