        for epoch in range(2000): # Train on explicit multistep state prediction rather than fitting test outputs.
            indices=torch.tensor(rng.integers(0,len(states),512));time_index=torch.tensor(rng.integers(0,T-9,512));state=state_tensor[indices,time_index];theta=model(zt[indices]);loss=torch.tensor(0.) # Sample bounded eight-step training windows with true initial state.
